package syn; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.state.*; import net.minecraft.world.level.block.state.properties.*; public class TripleBlock extends Block { public static final IntegerProperty ZED = IntegerProperty.create("zed", 0, 2); public static final BooleanProperty MID = BooleanProperty.create("mid"); public static final IntegerProperty ALPHA = IntegerProperty.create("alpha", 1, 2); public TripleBlock(BlockBehaviour.Properties p) { super(p); } @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> b) { b.add(ZED, MID, ALPHA); } }
